// ---------- Dietas rotativas (Premium) ----------
// O conteúdo das dietas fica em public/dietas.json (arquivo separado, buscado uma
// vez via fetch — assim não pesa o pacote JS do app, mesmo com muitas dietas).
// Formato de cada dieta: título + 2 opções (hipertrofia/emagrecimento), cada uma com 4 refeições.

function PremiumTab({ isPremium, onVerPlanos, objetivoUsuario, nivelUsuario }) {
  const objetivoPadrao = objetivoUsuario === "emagrecer" || objetivoUsuario === "secar" ? "emagrecer" : "hipertrofia";
  const perfilPadrao = nivelUsuario ? nivelUsuario.toLowerCase() : "iniciante";

  const [dietaIndice, setDietaIndice] = useState(0);
  const [dietaCarregada, setDietaCarregada] = useState(false);
  const [objetivoDieta, setObjetivoDieta] = useState(objetivoPadrao);
  const [perfilDieta, setPerfilDieta] = useState(perfilPadrao);
  const [faixaDieta, setFaixaDieta] = useState("18-60");
  const [cliquesHoje, setCliquesHoje] = useState(0);
  const [dietas, setDietas] = useState([]);
  const [alternativasAbertas, setAlternativasAbertas] = useState({}); // { "Café da manhã": true }
  const jaAplicouPadrao = useRef(false);

  useEffect(() => {
    // aplica o objetivo/nível do onboarding assim que chegarem, só uma vez —
    // depois disso a pessoa pode trocar livremente pelos seletores
    if (jaAplicouPadrao.current) return;
    if (objetivoUsuario || nivelUsuario) {
      setObjetivoDieta(objetivoPadrao);
      setPerfilDieta(perfilPadrao);
      jaAplicouPadrao.current = true;
    }
  }, [objetivoUsuario, nivelUsuario]);

  const hojeStr = new Date().toISOString().slice(0, 10);
  const LIMITE_DIARIO = 2;

  useEffect(() => {
    (async () => {
      // busca as dietas só uma vez; o navegador guarda em cache depois disso
      if (isPremium) {
        try {
          const resp = await fetch("/dietas.json");
          if (resp.ok) {
            const dados = await resp.json();
            const lista = dados.dietas || dados || [];
            setDietas(lista);
            try {
              await window.storage.set("dietas-cache", JSON.stringify(lista));
            } catch (e) {
              // não conseguiu guardar cópia offline, sem problema
            }
          }
        } catch (e) {
          // sem conexão agora — tenta usar a cópia salva de quando abriu com internet
          try {
            const cache = await window.storage.get("dietas-cache");
            if (cache && cache.value) setDietas(JSON.parse(cache.value));
          } catch (e2) {
            // nunca abriu com internet ainda pra ter uma cópia salva
          }
        }
      }
      try {
        const res = await window.storage.get("dieta-indice");
        if (res && res.value !== undefined && res.value !== null) {
          const n = parseInt(res.value, 10);
          if (!isNaN(n)) setDietaIndice(n);
        }
      } catch (e) {
        // primeira vez, começa na dieta 0
      }
      try {
        const cliquesRes = await window.storage.get("dieta-cliques-hoje");
        if (cliquesRes && cliquesRes.value) {
          const salvo = JSON.parse(cliquesRes.value);
          if (salvo.data === hojeStr) setCliquesHoje(salvo.contagem);
        }
      } catch (e) {
        // sem cliques registrados hoje ainda
      }
      setDietaCarregada(true);
    })();
  }, [isPremium]);

  const limiteAtingido = cliquesHoje >= LIMITE_DIARIO;

  const dietasFiltradas = dietas.filter(
    (d) => d.objetivo === objetivoDieta && d.perfil === perfilDieta && (d.faixa_etaria === faixaDieta || faixaDieta === "18-60")
  );

  const proximaDieta = () => {
    if (dietasFiltradas.length === 0 || limiteAtingido) return;
    const novoIndice = (dietaIndice + 1) % dietasFiltradas.length;
    const novaContagem = cliquesHoje + 1;
    setDietaIndice(novoIndice);
    setCliquesHoje(novaContagem);
    setAlternativasAbertas({});
    window.storage.set("dieta-indice", String(novoIndice)).catch(() => {});
    window.storage.set("dieta-cliques-hoje", JSON.stringify({ data: hojeStr, contagem: novaContagem })).catch(() => {});
  };

  const dietaAtual = dietasFiltradas.length > 0 ? dietasFiltradas[dietaIndice % dietasFiltradas.length] : null;

  return (
    <div>
      <section style={styles.card}>
        <div style={styles.cardLabel}>🍽 Sua dieta</div>
        {!isPremium ? (
          <p style={{ ...styles.modalDisclaimer, ...styles.premiumMuted }}>
            Disponível pra quem assina o Premium — dietas prontas, uma por vez, no seu ritmo.
          </p>
        ) : !dietaCarregada ? null : dietas.length === 0 ? (
          <p style={{ ...styles.modalDisclaimer, ...styles.premiumMuted }}>Em breve — as dietas ainda estão sendo cadastradas.</p>
        ) : (
          <>
            <p style={{ ...styles.modalDisclaimer, ...styles.premiumMuted }}>
              Conteúdo educativo — não substitui acompanhamento de um nutricionista.
            </p>

            <div style={styles.dietaOpcoesRow}>
              <button
                style={{ ...styles.dietaOpcaoBtn, ...(objetivoDieta === "hipertrofia" ? styles.dietaOpcaoBtnAtiva : {}) }}
                onClick={() => { setObjetivoDieta("hipertrofia"); setDietaIndice(0); }}
              >
                Hipertrofia
              </button>
              <button
                style={{ ...styles.dietaOpcaoBtn, ...(objetivoDieta === "emagrecer" ? styles.dietaOpcaoBtnAtiva : {}) }}
                onClick={() => { setObjetivoDieta("emagrecer"); setDietaIndice(0); }}
              >
                Emagrecimento
              </button>
            </div>

            <div style={styles.dietaFiltrosRow}>
              <label style={{ ...styles.dietaFiltroLabel, ...styles.premiumMuted }}>
                Nível
                <select
                  value={perfilDieta}
                  onChange={(e) => { setPerfilDieta(e.target.value); setDietaIndice(0); }}
                  style={styles.dietaFiltroSelect}
                >
                  <option value="iniciante">Iniciante</option>
                  <option value="intermediário">Intermediário</option>
                  <option value="avançado">Avançado</option>
                  <option value="prático">Prático</option>
                </select>
              </label>
              <label style={{ ...styles.dietaFiltroLabel, ...styles.premiumMuted }}>
                Faixa etária
                <select
                  value={faixaDieta}
                  onChange={(e) => { setFaixaDieta(e.target.value); setDietaIndice(0); }}
                  style={styles.dietaFiltroSelect}
                >
                  <option value="18-60">Todas</option>
                  <option value="18-30">18-30</option>
                  <option value="31-45">31-45</option>
                  <option value="46-60">46-60</option>
                </select>
              </label>
            </div>

            {!dietaAtual ? (
              <p style={{ ...styles.modalDisclaimer, ...styles.premiumMuted }}>Nenhuma dieta encontrada com esses filtros ainda.</p>
            ) : (
              <div style={styles.dietaCard}>
                <div style={styles.dicaDietaTitulo}>{dietaAtual.nome}</div>
                {dietaAtual.meta_nutricional && (
                  <div style={styles.dietaMacros}>
                    ~{dietaAtual.meta_nutricional.calorias_aprox} kcal · P {dietaAtual.meta_nutricional.proteinas_g}g · C {dietaAtual.meta_nutricional.carboidratos_g}g · G {dietaAtual.meta_nutricional.gorduras_g}g
                  </div>
                )}
                {dietaAtual.refeicoes.map((r) => (
                  <div key={r.nome} style={{ ...styles.dietaRefeicao, ...styles.premiumMuted }}>
                    <span style={styles.dietaRefeicaoNome}>{r.nome}:</span> {r.opcao_principal}
                    {r.alternativas && r.alternativas.length > 0 && (
                      <>
                        <button
                          style={styles.dietaAltToggle}
                          onClick={() => setAlternativasAbertas((prev) => ({ ...prev, [r.nome]: !prev[r.nome] }))}
                        >
                          {alternativasAbertas[r.nome] ? "▲ ocultar opções" : "▼ ver outras opções"}
                        </button>
                        {alternativasAbertas[r.nome] && (
                          <ul style={styles.dietaAltLista}>
                            {r.alternativas.map((alt, i) => (
                              <li key={i}>{alt}</li>
                            ))}
                          </ul>
                        )}
                      </>
                    )}
                  </div>
                ))}
              </div>
            )}

            <button style={styles.saveButton} onClick={proximaDieta} disabled={limiteAtingido || !dietaAtual}>
              {limiteAtingido ? "Limite de hoje atingido — volte amanhã" : "🔁 Ver outra dieta"}
            </button>
            {!limiteAtingido && (
              <p style={{ ...styles.dietaLimiteTexto, ...styles.premiumMuted }}>
                {LIMITE_DIARIO - cliquesHoje} de {LIMITE_DIARIO} trocas disponíveis hoje
              </p>
            )}
          </>
        )}
      </section>

      <section style={styles.card}>
        <div style={styles.cardLabel}>★ Dicas gerais de dieta</div>
        <p style={{ ...styles.modalDisclaimer, ...styles.premiumMuted }}>
          Conteúdo educativo geral, disponível pra todo mundo — não substitui acompanhamento de um nutricionista.
        </p>
        {DICAS_DIETA.map((d) => (
          <div key={d.titulo} style={styles.dicaDietaItem}>
            <div style={styles.dicaDietaTitulo}>{d.titulo}</div>
            <p style={styles.notaTexto}>{d.texto}</p>
          </div>
        ))}
      </section>

      {!isPremium && (
        <section style={styles.card}>
          <div style={styles.cardLabel}>Quer mais?</div>
          <p style={styles.notaTexto}>Assinantes Premium têm acesso a conteúdo extra conforme o app evolui.</p>
          <button style={styles.saveButton} onClick={onVerPlanos}>Ver planos</button>
        </section>
      )}
    </div>
  );
}

function SobreTab({ t, onIniciarTour }) {
  const [mensagemBackup, setMensagemBackup] = useState(null);
  const [manualAberto, setManualAberto] = useState(null);

  const MANUAL_SECOES = [
    { titulo: "🏠 Início", texto: "Mostra um resumo do seu dia: o treino de hoje (toque no card pra abrir direto na Rotina no dia certo), seu peso mais recente, sua sequência de dias treinados e o resumo da semana." },
    { titulo: "💪 Rotina", texto: "Monte seu treino por dia da semana. Em cada exercício, escolha o equipamento (halteres, barra ou máquina) no menu logo abaixo do nome. Toque no nome do exercício pra ver o vídeo de execução e a explicação completa. Ajuste séries, repetições, carga por série e o tempo de descanso. Use \"Iniciar guiado\" pra ser conduzido exercício por exercício, com cronômetro de descanso automático." },
    { titulo: "📅 Histórico", texto: "Veja quantos treinos você já concluiu, sua sequência atual de dias seguidos, as conquistas/medalhas desbloqueadas e um mapa de consistência do mês." },
    { titulo: "📝 Notas", texto: "Registre observações sobre exercícios, cargas usadas e sensações após o treino. Use a busca e o filtro por período pra encontrar anotações antigas." },
    { titulo: "📏 Avaliação", texto: "Registre seu peso, medidas corporais e fotos de progresso ao longo do tempo. A calculadora de água te dá uma meta diária de hidratação." },
    { titulo: "⭐ Premium", texto: "Acesso a dietas prontas (trocáveis) organizadas por objetivo, e dicas gerais de alimentação disponíveis pra todo mundo." },
    { titulo: "🔥 Massi Cross", texto: "Treinos no estilo funcional: WOD do dia, gerador de treino rápido, biblioteca de exercícios com vídeo, cronômetro (AMRAP, EMOM, FORTIME, TABATA), desafios com progresso e acompanhamento de desempenho." },
  ];

  const exportarDados = async () => {
    const dados = {};
    for (const chave of CHAVES_BACKUP) {
      try {
        const res = await window.storage.get(chave);
        if (res && res.value) dados[chave] = res.value;
      } catch (e) {
        // chave sem valor salvo, segue
      }
    }
    const blob = new Blob([JSON.stringify(dados, null, 2)], { type: "application/json" });
    const url = URL.createObjectURL(blob);
    const a = document.createElement("a");
    a.href = url;
    a.download = `massi-pro-backup-${new Date().toISOString().slice(0, 10)}.json`;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);
  };

  const importarDados = async (e) => {
    const arquivo = e.target.files && e.target.files[0];
    if (!arquivo) return;
    try {
      const texto = await arquivo.text();
      const dados = JSON.parse(texto);
      for (const chave of CHAVES_BACKUP) {
        if (dados[chave] !== undefined) {
          await window.storage.set(chave, dados[chave]);
        }
      }
      setMensagemBackup(t("sobreBackupImportado"));
    } catch (err) {
      setMensagemBackup(t("sobreBackupErro"));
    }
    e.target.value = "";
  };

  const [copiadoConvite, setCopiadoConvite] = useState(false);
  const textoConvite = t("sobreTextoConvite");

  const convidarWhatsapp = () => {
    window.open(`https://wa.me/?text=${encodeURIComponent(textoConvite)}`, "_blank");
  };

  const convidarMaisOpcoes = async () => {
    if (typeof navigator !== "undefined" && navigator.share) {
      try {
        await navigator.share({ text: textoConvite });
      } catch (e) {
        // pessoa cancelou o compartilhamento, sem problema
      }
    }
  };

  const copiarConvite = async () => {
    try {
      await navigator.clipboard.writeText(textoConvite);
      setCopiadoConvite(true);
      setTimeout(() => setCopiadoConvite(false), 2500);
    } catch (e) {
      // clipboard indisponível, sem problema
    }
  };

  return (
    <div>
      <section style={styles.card}>
        <div style={styles.cardLabel}>{t("sobreTitulo")}</div>
        <p style={styles.notaTexto}>
          {t("sobreTexto")}
        </p>
      </section>

      <section style={styles.card}>
        <div style={styles.cardLabel}>📖 Manual do app</div>
        <p style={styles.notaTexto}>Toque numa aba pra ver o que ela faz.</p>
        {MANUAL_SECOES.map((s) => (
          <div key={s.titulo} style={{ borderTop: "1px solid rgba(255,255,255,0.08)", paddingTop: 10, marginTop: 10 }}>
            <button
              onClick={() => setManualAberto(manualAberto === s.titulo ? null : s.titulo)}
              style={{ ...styles.trocarBtn, width: "100%", textAlign: "left", display: "flex", justifyContent: "space-between", background: "transparent", border: "none", padding: "4px 0" }}
            >
              <span style={{ fontWeight: 700, fontSize: 14, color: "#F6F7F9" }}>{s.titulo}</span>
              <span>{manualAberto === s.titulo ? "−" : "+"}</span>
            </button>
            {manualAberto === s.titulo && <p style={styles.notaTexto}>{s.texto}</p>}
          </div>
        ))}
        <button style={{ ...styles.addItemBtn, marginTop: 14 }} onClick={onIniciarTour}>
          ▶ Ver o tutorial guiado da Rotina de novo
        </button>
        <div style={{ borderTop: "1px solid rgba(255,255,255,0.08)", paddingTop: 10, marginTop: 10 }}>
          <button
            onClick={() => setManualAberto(manualAberto === "diagnostico" ? null : "diagnostico")}
            style={{ ...styles.trocarBtn, width: "100%", textAlign: "left", display: "flex", justifyContent: "space-between", background: "transparent", border: "none", padding: "4px 0" }}
          >
            <span style={{ fontWeight: 700, fontSize: 14, color: "#F6F7F9" }}>🛠 Diagnóstico de vídeos</span>
            <span>{manualAberto === "diagnostico" ? "−" : "+"}</span>
          </button>
          {manualAberto === "diagnostico" && (() => {
            const semVideoReal = AUDITORIA_VIDEOS.filter((f) => !f.usaCanal);
            if (semVideoReal.length === 0) {
              return <p style={styles.notaTexto}>✅ Todo exercício e máquina cadastrados têm vídeo específico.</p>;
            }
            return (
              <div>
                <p style={styles.notaTexto}>
                  {semVideoReal.length} combinação(ões) de exercício + equipamento ainda sem vídeo específico (o app mostra busca do YouTube nesses casos):
                </p>
                {semVideoReal.map((f, i) => (
                  <p key={i} style={{ ...styles.notaTexto, margin: "2px 0" }}>
                    • {f.nome} — {f.maquina} ({f.grupo})
                  </p>
                ))}
              </div>
            );
          })()}
        </div>
      </section>

      <section style={styles.card}>
        <div style={styles.cardLabel}>{t("sobreConviteTitulo")}</div>
        <p style={styles.notaTexto}>{t("sobreConviteTexto")}</p>
        <div style={styles.convidarBotoesRow}>
          <button style={styles.convidarBtnWhats} onClick={convidarWhatsapp}>{t("sobreConviteWhats")}</button>
          {typeof navigator !== "undefined" && navigator.share && (
            <button style={styles.convidarBtnOutro} onClick={convidarMaisOpcoes}>{t("sobreConviteMaisOpcoes")}</button>
          )}
          <button style={styles.convidarBtnOutro} onClick={copiarConvite}>
            {copiadoConvite ? t("sobreConviteCopiado") : t("sobreConviteCopiarLink")}
          </button>
        </div>
      </section>

      <section style={styles.card}>
        <div style={styles.cardLabel}>{t("sobreBackupTitulo")}</div>
        <p style={styles.notaTexto}>{t("sobreBackupTexto")}</p>
        <button style={styles.saveButton} onClick={exportarDados}>{t("sobreBackupExportar")}</button>
        <label style={styles.addItemBtn}>
          {t("sobreBackupImportar")}
          <input type="file" accept="application/json" onChange={importarDados} style={{ display: "none" }} />
        </label>
        {mensagemBackup && <p style={styles.modalDisclaimer}>{mensagemBackup}</p>}
      </section>
      <section style={styles.card}>
        <div style={styles.cardLabel}>{t("sobreTermosTitulo")}</div>
        <p style={styles.notaTexto}>
          {t("sobreTermosTexto1")}
        </p>
        <p style={styles.notaTexto}>
          {t("sobreTermosTexto2")}
        </p>
      </section>
    </div>
  );
}

